+pub(crate) fn temporary_startup_probe() -> Option<std::time::Instant> {
+    std::env::var_os("NARA_TEMP_STARTUP_ATTRIBUTION")
+        .is_some()
+        .then(std::time::Instant::now)
+}
+
+pub(crate) fn finish_temporary_startup_probe(label: &str, started: Option<std::time::Instant>) {
+    if let Some(started) = started {
+        eprintln!("nara_temp_startup label={label} ns={}", started.elapsed().as_nanos());
+    }
+}
